// 真实本域writer与Common缓存分配验证永久提交边界；typed成功effect读不冒World运行。
#define POLITICAL_HEAD_HANDOVER_RULES_FIXTURE_ONLY
#include "political_head_handover_rules_test.cpp"
#undef POLITICAL_HEAD_HANDOVER_RULES_FIXTURE_ONLY
#include "resident/domains/politics/head_handover/political_head_handover_receipts.hpp"
#include "resident/checkpoint/codec_visitor.hpp"
namespace {
struct HandoverReceiptFixture:HandoverFixture {

 // 原请求序号/结果revision/全局history实际分配后才绑定业务源。
 StableId commit(const StableId& actor,PoliticalHeadHandoverCommand command,Integer request){auto before=handovers;auto id=submit_handover(actor,command);auto kind=political_head_handover_command_kind(command);check(take(political_head_handover_new_player_source(before,handovers,actor,kind,common.tick()))==id,"actual unique business source selected");auto r=std::make_shared<CommitResult>();r->ok=true;r->kind=kind;r->tick=common.tick();r->revision=++common.state().identity.revision;r->result_id=take(common.next_id("result"));common.state().request_sequences.set(actor,request);common.state().results.insert(actor+":"+std::to_string(request),r);common.state().history.push_back({r->tick,r->kind,actor,r->result_id,{}});check(bind_political_head_handover_player_result(common,handovers,id,actor,request,*r,[&](const CommitResult&,const StableId& source,const StableId& office){const auto* a=handovers.answers.find(id);return source==id&&office==(a?a->office_change_fact_id:StableId{});}).ok,"real cache object binds exact source");return id;}
 Status valid(){return validate_political_head_handover_player_results(common,handovers,[this](const CommitResult&,const StableId& source,const StableId& office){const auto* a=handovers.answers.find(source);return office==(a?a->office_change_fact_id:StableId{});});}
};
}
#ifndef POLITICAL_HEAD_HANDOVER_RECEIPTS_FIXTURE_ONLY
int main(){try{
 HandoverReceiptFixture f;auto first=f.commit("leader",f.offer_command(),1);auto decline=f.commit("candidate",PoliticalAnswerHeadHandover{first,false,0},1);auto second=f.commit("leader",f.offer_command(),2);auto later=f.commit("candidate",PoliticalAnswerHeadHandover{second,false,0},2);check(f.valid().ok,"interleaved actors retain unique actual results");
 HandoverReceiptFixture installed;auto live=installed.commit("leader",installed.offer_command(),1);auto actual=installed.commit("candidate",PoliticalAnswerHeadHandover{live,true,0},1);check(installed.valid().ok&&!installed.handovers.answers.find(actual)->office_change_fact_id.empty(),"actual acceptance result follows both source and original Office head");
 auto raw=encode_political_head_handover_state(f.handovers);auto decoded=take(decode_political_head_handover_state(raw));check(compare_boundary(raw,encode_political_head_handover_state(decoded)).exact(),"strict new state JSON preserves bindings");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);take(visit_political_head_handover_checkpoint(writer,decoded));take(writer.finish());const auto& fixed=bytes;CodecVisitor reader(fixed);PoliticalHeadHandoverState restored;take(visit_political_head_handover_checkpoint(reader,restored));take(reader.finish());check(compare_boundary(raw,encode_political_head_handover_state(restored)).exact(),"new independent binary tail preserves exact state");
 auto saved=f.handovers;auto common=f.common.state();auto last=*f.common.state().results.find("candidate:2");f.common.state().results={};f.common.state().results.insert("candidate:2",last);f.common.state().history.erase(f.common.state().history.begin(),f.common.state().history.end()-1);check(f.valid().ok,"only last true cache/history may remain");f.handovers.answers.erase(later);f.common.state().facts.erase(later);check(!f.valid().ok,"deleted later payload/header cannot hang first retained result on old same-tick decline");
 f.handovers=saved;f.common.state()=common;f.handovers.answers.find(later)->player_receipt.reset();check(!f.valid().ok,"no empty receipt becomes an NPC source");auto copied=*last;check(!bind_political_head_handover_player_result(f.common,f.handovers,later,"candidate",2,copied,[](const auto&,const auto&,const auto&){return true;}).ok,"identical result copy is not original cache object");check(!f.handovers.answers.find(later)->player_receipt,"failed actual-result check has no partial write");check(bind_political_head_handover_player_result(f.common,f.handovers,later,"candidate",2,*last,[](const auto&,const auto&,const auto&){return true;}).ok,"original actual result completes only its pending binding");
 check(!political_head_handover_new_player_source(f.handovers,f.handovers,"candidate",political_head_handover_answer_command,0).ok,"request replay never invents a new source");check(!validate_political_head_handover_player_results(f.common,f.handovers,[](const auto&,const auto&,const auto&){return false;}).ok,"wrong typed effect cannot borrow successful command name");auto before_new=f.handovers;auto next_id=f.submit_handover("leader",f.offer_command());auto modified=f.handovers;modified.offers.find(first)->candidate_actor_id="deputy";check(!political_head_handover_new_player_source(before_new,modified,"leader",political_head_handover_offer_command,0).ok,"one genuine new nomination still cannot mutate an old bound source");f.common.state()=common;f.handovers=saved;
 f.handovers.answers.find(later)->player_receipt=f.handovers.answers.find(decline)->player_receipt;check(!f.valid().ok,"two original answers cannot share one actual result");restored.version=2;check(!decode_political_head_handover_state(encode_political_head_handover_state(restored)).ok,"unknown new segment version rejected");
 for(const PoliticalHeadHandoverCommand& command:std::vector<PoliticalHeadHandoverCommand>{f.offer_command(),PoliticalAnswerHeadHandover{first,true,0},PoliticalWithdrawHeadHandover{{"city","chief",0,"leader"},second}}){auto kind=political_head_handover_command_kind(command);auto value=encode_political_head_handover_command(command);check(compare_boundary(value,encode_political_head_handover_command(take(decode_political_head_handover_command(kind,value)))).exact(),"three exact handover commands preserve only caller selections");}

 std::cout<<checks<<" checks; source fixture only, no World run claimed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}

#endif
